import{_ as a,o as i,c as e,a4 as n}from"./chunks/framework.DzJZdBQK.js";const t="/assets/crdential.CdlJ9ajQ.png",k=JSON.parse('{"title":"管理多个Github帐号","description":"","frontmatter":{"date":"2018-09-19T08:15:40","title":"管理多个Github帐号","categories":["git","GitHub","ssh"],"tags":["git","GitHub","ssh"]},"headers":[{"level":2,"title":"起因","slug":"起因","link":"#起因","children":[]},{"level":2,"title":"初步方案","slug":"初步方案","link":"#初步方案","children":[]},{"level":2,"title":"最终方案","slug":"最终方案","link":"#最终方案","children":[]},{"level":2,"title":"增加Mac的配置","slug":"增加mac的配置","link":"#增加mac的配置","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"参考链接","slug":"参考链接","link":"#参考链接","children":[]}],"relativePath":"posts/git/git-1.md","filePath":"posts/git/git-1.md"}'),p={name:"posts/git/git-1.md"};function l(h,s,o,r,c,d){return i(),e("div",null,[...s[0]||(s[0]=[n('<h2 id="起因" tabindex="-1">起因 <a class="header-anchor" href="#起因" aria-label="Permalink to &quot;起因&quot;">​</a></h2><p>之前通过GithubPages和Hexo搭建了个人博客，在<a href="https://l4qiang.me/2016/10/05/hexo/" target="_blank" rel="noreferrer">这里</a>可看到搭建的方法。现在呢，希望用另一个帐号，管理一个不同内容的<a href="http://goldyear.info" target="_blank" rel="noreferrer">博客</a>。有了之前的经验，整个搭建的过程还是比较顺利，主要碰到的问题就是代码发布。之前github帐号，是通过Windows的<a href="https://www.howto-connect.com/how-to-use-credential-manager-windows-10/" target="_blank" rel="noreferrer">凭证管理</a>来实现的，按理说Github配置了多个帐号也是可以管理的。如图：</p><p><img src="'+t+`" alt="crdential.png"></p><p>但是两套博客在发布代码的时候都出现了问题。</p><h2 id="初步方案" tabindex="-1">初步方案 <a class="header-anchor" href="#初步方案" aria-label="Permalink to &quot;初步方案&quot;">​</a></h2><p>将用户名和密码配置在Hexo的<code>_config.yml</code>的配置项中，形如</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://enderjo:xyz@github.com/enderjo/enderjo.github.io</span></span></code></pre></div><p>虽然这样配置是解决了发布问题，但密码安全问题就暴露出来了，想想之前有了解到Github有ssh功能，但也没用过，初步试了下一样发现两个帐号配置的问题，github不支持同一个公钥用于不同的帐号，会提示公钥已经被使用了，请教了下前同事事了解到ssh有个config的配置。</p><h2 id="最终方案" tabindex="-1">最终方案 <a class="header-anchor" href="#最终方案" aria-label="Permalink to &quot;最终方案&quot;">​</a></h2><p>基于同事的提示刚开始创建的config如下:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host github:enderjo</span></span>
<span class="line"><span> Hostname github.com</span></span>
<span class="line"><span> User git</span></span>
<span class="line"><span> PreferredAuthentications publickey</span></span>
<span class="line"><span> IdentityFile ~/.ssh/github-enderjo/id_rsa</span></span></code></pre></div><p>Window中在用户目录<code>%USERPROFILE%</code>下。之后使用ssh测试也是通的。 如下：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> github.com:enderjo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Hi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enderjo!</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> You&#39;ve successfully authenticated, but GitHub does not provide shell access.</span></span></code></pre></div><p>但测试Git Clone的时候提示无法</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com:enderjo/enderjo.github.io.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Cloning</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> into</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;enderjo.github.io&#39;...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git@github.com:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Permission</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> denied</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (publickey).</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fatal:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Could</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> not</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> read</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Please</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> you</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> have</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> correct</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rights</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repository</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exists.</span></span></code></pre></div><p>参考<a href="https://help.github.com/articles/error-permission-denied-publickey/" target="_blank" rel="noreferrer">Error: Permission denied (publickey)</a>通过ssh-add证书的方式，能正常git clone。此时已可初步判断，git clone没有正常取到config的配置。 接着同事发来这篇文章 <a href="https://gitlab.com/gitlab-org/gitlab-ce/issues/45593" target="_blank" rel="noreferrer">https://gitlab.com/gitlab-org/gitlab-ce/issues/45593</a> 其中提到，可通过如下命令查看git clone的实际执行过程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GIT_TRACE=1 GIT_SSH_COMMAND=&quot;ssh -vvv&quot; git clone git@gitlab.example.com:my-group/my-project.git</span></span></code></pre></div><p>测试后的部分代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ GIT_TRACE=1 GIT_SSH_COMMAND=&quot;ssh -vvv&quot; git clone git@github.com:enderjo/enderjo.github.io.git</span></span>
<span class="line"><span>14:03:51.164492 exec-cmd.c:236          trace: resolved executable dir: C:/Program Files/Git/mingw64/bin</span></span>
<span class="line"><span>14:03:51.165492 git.c:415               trace: built-in: git clone git@github.com:enderjo/enderjo.github.io.git</span></span>
<span class="line"><span>Cloning into &#39;enderjo.github.io&#39;...</span></span>
<span class="line"><span>14:03:51.225463 run-command.c:637       trace: run_command: unset GIT_DIR; &#39;ssh -vvv&#39; git@github.com &#39;git-upload-pack &#39;\\&#39;&#39;enderjo/enderjo.github.io.git&#39;\\&#39;&#39;&#39;</span></span></code></pre></div><p>此时我们可以看到，实际执行的地址和测试的地址是不一样的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ ssh -T git@github.com:enderjo</span></span>
<span class="line"><span>$ ssh -vvv git@github.com</span></span></code></pre></div><p>ssh命令是根据config文件中Host记录与ssh命令时所输入的主机名来进行匹配的，而git clone因为使用<code>:</code>分隔用户名。</p><p>之后查到<a href="https://blog.csdn.net/huasonl88/article/details/52166876" target="_blank" rel="noreferrer">这篇</a>文章。config文件中的Host就是一个别名。</p><p>调整config</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host gh-enderjo</span></span>
<span class="line"><span> Hostname github.com</span></span>
<span class="line"><span> User git</span></span>
<span class="line"><span> PreferredAuthentications publickey</span></span>
<span class="line"><span> IdentityFile ~/.ssh/github-enderjo/id_rsa</span></span></code></pre></div><p>修改git clone命令</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git clone gh-enderjo:enderjo/enderjo.github.io.git</span></span>
<span class="line"><span>Cloning into &#39;enderjo.github.io&#39;...</span></span>
<span class="line"><span>remote: Counting objects: 4822, done.</span></span>
<span class="line"><span>remote: Compressing objects: 100% (386/386), done.</span></span>
<span class="line"><span>remote: Total 4822 (delta 873), reused 2292 (delta 846), pack-reused 2496</span></span>
<span class="line"><span>Receiving objects: 100% (4822/4822), 5.20 MiB | 215.00 KiB/s, done.</span></span>
<span class="line"><span>Resolving deltas: 100% (1686/1686), done.</span></span></code></pre></div><p>测试正常，修改Hexo的_config.yml也能正常发布代码了。</p><h2 id="增加mac的配置" tabindex="-1">增加Mac的配置 <a class="header-anchor" href="#增加mac的配置" aria-label="Permalink to &quot;增加Mac的配置&quot;">​</a></h2><p>因为之前配置过了Windows，这里我需要把Windows中的ssh配置先拷贝到Mac上（~/.ssh）。 测试，此时会提示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Permissions 0755 for &#39;/Users/airhead/.ssh/github-enderjo/id_rsa&#39; are too open.</span></span>
<span class="line"><span>It is required that your private key files are NOT accessible by others.</span></span>
<span class="line"><span>This private key will be ignored.</span></span>
<span class="line"><span>Load key &quot;/Users/airhead/.ssh/github-enderjo/id_rsa&quot;: bad permissions</span></span>
<span class="line"><span>git@github.com: Permission denied (publickey).</span></span>
<span class="line"><span>fatal: Could not read from remote repository.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please make sure you have the correct access rights</span></span></code></pre></div><p>需要修改权限为400（600也可以），注意修改路径</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chmod 400 /Users/airhead/.ssh/github-enderjo/id_rsa</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>利用ssh的config功能可以很好的管理Git的多帐号问题，但需要注意修改Git仓库的获取地址。</p><p>虽然一直有使用Git，但对于Git和ssh还是有很多不了解的地方。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><p><a href="https://help.github.com/articles/error-permission-denied-publickey/" target="_blank" rel="noreferrer">Error: Permission denied (publickey)</a><a href="https://gitlab.com/gitlab-org/gitlab-ce/issues/45593" target="_blank" rel="noreferrer">https://gitlab.com/gitlab-org/gitlab-ce/issues/45593</a><a href="https://blog.csdn.net/huasonl88/article/details/52166876" target="_blank" rel="noreferrer">ssh-config配置</a><a href="https://deepzz.com/post/how-to-setup-ssh-config.html" target="_blank" rel="noreferrer">SSH Config 那些你所知道和不知道的事</a></p>`,38)])])}const u=a(p,[["render",l]]);export{k as __pageData,u as default};
